import{_ as t,o,c as a,ah as r}from"./chunks/framework.BsNNkeaH.js";const m=JSON.parse('{"title":"Homeroom and schedule","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/enseignant/registre-et-emploi-du-temps.md","filePath":"src/en/guide/enseignant/registre-et-emploi-du-temps.md"}'),s={name:"en/guide/enseignant/registre-et-emploi-du-temps.md"};function n(d,e,i,l,h,c){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="homeroom-and-schedule" tabindex="-1">Homeroom and schedule <a class="header-anchor" href="#homeroom-and-schedule" aria-label="Permalink to &quot;Homeroom and schedule&quot;">​</a></h1><p>This page covers two independent things: your homeroom class register if you are a homeroom teacher, and your own schedule, available to every teacher.</p><h2 id="the-homeroom-class-register" tabindex="-1">The homeroom class register <a class="header-anchor" href="#the-homeroom-class-register" aria-label="Permalink to &quot;The homeroom class register&quot;">​</a></h2><p>If you are designated homeroom teacher for one or more classes, <strong>Teaching → My homeroom class</strong> gives you a consolidated view of each of them.</p><p>For each class, a table summarizes, per student:</p><table tabindex="0"><thead><tr><th>Column</th><th>Content</th></tr></thead><tbody><tr><td>Student</td><td>Student&#39;s name</td></tr><tr><td>Annual average</td><td>The student&#39;s average for the year, across all subjects</td></tr><tr><td>Unjustified absences</td><td>Number of absences with no approved justification</td></tr><tr><td>Discipline incidents</td><td>Number of incidents recorded for this student</td></tr></tbody></table><p>This table is a read-only tracking view. Next to each class&#39;s name, the <strong>End-of-period appreciations</strong> button takes you to the entry screen described in <a href="/en/guide/enseignant/bulletins-et-cahier-texte.html">Report cards and lesson log</a>.</p><p>If you are not currently the homeroom teacher of any class, the page says so and offers nothing else.</p><h2 id="view-your-schedule" tabindex="-1">View your schedule <a class="header-anchor" href="#view-your-schedule" aria-label="Permalink to &quot;View your schedule&quot;">​</a></h2><p><strong>Teaching → My schedule</strong> shows your class sessions for the week: day, start time, end time, class and subject. The <strong>Export (iCal)</strong> button downloads your schedule as a file you can import into your personal calendar app (Google Calendar, Outlook, Apple Calendar…).</p>',10)])])}const p=t(s,[["render",n]]);export{m as __pageData,p as default};
